async function runBatch(
  mode: QualityMode,
  projectRoot: string,
  files: readonly string[],
): Promise<BatchResult> {
  const args = mode === 'check'
    ? ['check', '--unstable-kv', ...files]
    : mode === 'lint'
    ? ['lint', '--no-config', ...files]
    : mode === 'fmt-check'
    ? ['fmt', '--check', ...files]
    : ['fmt', ...files];
  const output = await new Deno.Command('deno', {
    args,
    cwd: projectRoot,
    stdout: 'piped',
